(function () {
/* PRODUCTS is generated by secrets/site-tools/build_seo_site.py and printed into the
   homepage markup from the private product list. Keep every change to the product
   data in that builder, not here, or the two will disagree. */
var PRODUCTS = window.MM_PRODUCTS || [];
var ORDER_ENDPOINT = "/api/orders";

var $ = function (id) { return document.getElementById(id); };
var cart = [];
try { cart = JSON.parse(localStorage.getItem("mm_cart") || "[]"); } catch (e) { cart = []; }

function rs(n) { return "₹" + Number(n).toLocaleString("en-IN"); }
function esc(s) { return String(s).replace(/[&<>\"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '\"': "&quot;" }[c]; }); }
function find(id) { return PRODUCTS.filter(function (p) { return p.id === id; })[0]; }
function save() { try { localStorage.setItem("mm_cart", JSON.stringify(cart)); } catch (e) {} }
function total() { return cart.reduce(function (s, i) { var p = find(i.id); return s + (p && p.price ? p.price * i.q : 0); }, 0); }
function updateBadge() { var el = $("count"); if (el) el.textContent = cart.reduce(function (s, i) { return s + i.q; }, 0); }

/* A cart line needs a real price before we can total or order it. Today the
   catalogue has no confirmed live prices, so those products are barred from the
   cart and the card offers WhatsApp instead. */
function sellable(p) { return !!p && (typeof p.price === "number") && p.price > 0; }

function waLink(text) { return "https://wa.me/919352531913?text=" + encodeURIComponent(text); }
function askLabel(p) { return (p.former ? "Price on request (former listed " + p.former + ")" : "Price on request"); }
function askMessage(p) {
  return "Hello! What is the current price and availability of " + p.name + (p.size ? " (" + p.size + ")" : "") + "?"
    + (p.former ? " I saw the former listed price " + p.former + "." : "");
}

function productImage(p) {
  var image = '<img src="' + p.img + '" alt="' + esc(p.name) + '" width="1200" height="800" loading="lazy">';
  return p.webp ? '<picture><source srcset="' + p.webp + '" type="image/webp">' + image + '</picture>' : image;
}

function card(p) {
  var pct = p.price && p.mrp > p.price ? Math.round((p.mrp - p.price) / p.mrp * 100) : 0;
  return '<article class="card">' + (p.featured && pct ? '<span class="badge">-' + pct + '%</span>' : '') +
    '<a href="' + p.url + '"><figure>' + productImage(p) + '</figure></a>' +
    '<div class="info"><p class="cat-label">' + esc(p.category) + '</p><h3><a href="' + p.url + '">' + esc(p.name) + '</a></h3>' +
    (p.size ? '<p class="size">' + esc(p.size) + '</p>' : '') +
    (sellable(p) ? '<p class="price">' + (pct ? '<s>' + rs(p.mrp) + '</s>' : '') + rs(p.price) + '</p>' : '<p class="price ask">' + askLabel(p) + '</p>') +
    (sellable(p) ? '<button class="btn solid" type="button" data-add="' + p.id + '">Add to cart</button>' : '<a class="btn" href="' + waLink(askMessage(p)) + '">Ask for price</a>') + '</div></article>';
}

var trending = PRODUCTS.filter(function (p) { return !p.featured; }).slice(0, 8);
var featured = PRODUCTS.filter(function (p) { return p.featured; });
var grid = $("grid");
if (grid) grid.innerHTML = trending.map(card).join("");
var featuredGrid = $("featured-grid");
var featuredSection = $("featured");
if (featuredGrid && featured.length) { featuredGrid.innerHTML = featured.map(card).join(""); } else if (featuredSection) { featuredSection.hidden = true; }

/* Hero slider */
var slides = document.querySelectorAll(".slide"), cur = 0, timer;
function show(n) { if (!slides.length) return; slides[cur].classList.remove("on"); cur = (n + slides.length) % slides.length; slides[cur].classList.add("on"); }
function auto() {
  clearInterval(timer);
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches || slides.length < 2) return;
  timer = setInterval(function () { show(cur + 1); }, 6000);
}
var prevButton = $("prev"), nextButton = $("next");
if (prevButton) prevButton.onclick = function () { show(cur - 1); auto(); };
if (nextButton) nextButton.onclick = function () { show(cur + 1); auto(); };
auto();

/* Mobile menu and search */
var menuButton = $("menu-btn");
if (menuButton) menuButton.onclick = function () { var n = $("nav"), o = n.classList.toggle("open"); this.setAttribute("aria-expanded", o); };

var searchButton = $("search-btn"), searchPanel = $("search-panel"), searchField = $("q");
if (searchButton) searchButton.onclick = function () { searchPanel.classList.toggle("on"); if (searchPanel.classList.contains("on")) searchField.focus(); };
if (searchField) searchField.addEventListener("input", function () {
  var q = this.value.trim().toLowerCase(), r = $("results");
  if (!q) { r.innerHTML = ""; return; }
  var hits = PRODUCTS.filter(function (p) { return (p.name + " " + p.category).toLowerCase().indexOf(q) > -1; });
  r.innerHTML = hits.length
    ? hits.map(function (p) { return '<li><a href="' + p.url + '">' + esc(p.name) + (sellable(p) ? ' — ' + rs(p.price) : '') + '</a></li>'; }).join("")
    : '<li class="note" style="padding:10px 4px">No products found.</li>';
});

/* Cart drawer. Shop.js is only loaded on the homepage, so every lookup is guarded. */
var drawer = $("drawer"), scrim = $("scrim");
function openCart() {
  if (!drawer || !scrim) return;
  drawer.classList.add("on");
  scrim.classList.add("on");
  drawer.setAttribute("aria-hidden", "false");
  render();
}
function closeCart() {
  if (!drawer || !scrim) return;
  drawer.classList.remove("on");
  scrim.classList.remove("on");
  drawer.setAttribute("aria-hidden", "true");
}
function change(id, d) {
  cart.forEach(function (i) { if (i.id === id) i.q += d; });
  cart = cart.filter(function (i) { return i.q > 0; });
  save(); updateBadge(); render();
}

function render() {
  var b = $("dbody");
  if (!b) return;
  if (!cart.length) {
    b.innerHTML = '<p class="empty">Your cart is empty. Pick a product and choose "Add to cart".</p>';
    return;
  }
  b.innerHTML = cart.map(function (i) {
    var p = find(i.id);
    if (!p) return "";
    return '<div class="line"><img src="' + p.img + '" alt=""><div><b>' + esc(p.name) + '</b><div class="qty">' +
      '<button type="button" data-d="-1" data-id="' + i.id + '" aria-label="Decrease quantity">−</button><span>' + i.q + '</span>' +
      '<button type="button" data-d="1" data-id="' + i.id + '" aria-label="Increase quantity">+</button></div></div><strong>' + (p.price ? rs(p.price * i.q) : '—') + '</strong></div>';
  }).join("") +
  '<div class="total"><span>Total</span><span>' + rs(total()) + '</span></div>' +
  '<form class="co" id="co" novalidate>' +
    '<label>Full name<input name="name" required autocomplete="name"></label>' +
    '<label>Phone number<input name="phone" required inputmode="numeric" maxlength="10" autocomplete="tel" placeholder="10-digit mobile number"></label>' +
    '<label>Full address<textarea name="addr" rows="3" required autocomplete="street-address"></textarea></label>' +
    '<div class="two"><label>City<input name="city" required autocomplete="address-level2"></label>' +
    '<label>Pincode<input name="pin" required inputmode="numeric" maxlength="6" autocomplete="postal-code"></label></div>' +
    '<label>Payment method<select name="pay"><option value="COD">Cash on delivery</option><option value="UPI">UPI (we send a link after confirming)</option></select></label>' +
    '<p class="error" id="err" role="alert"></p>' +
    '<button class="btn solid" type="submit">Place order</button>' +
    '<p class="note">We will call you to confirm the order, delivery charges and delivery date.</p>' +
  '</form>';
  $("co").addEventListener("submit", submit);
}

function submit(e) {
  e.preventDefault();
  var f = e.target, err = $("err");
  function v(n) { return f.elements[n].value.trim(); }
  if (!v("name") || !v("addr") || !v("city")) { err.textContent = "Name, address and city are required."; return; }
  if (!/^[6-9]\d{9}$/.test(v("phone"))) { err.textContent = "Enter a valid 10-digit mobile number."; return; }
  if (!/^\d{6}$/.test(v("pin"))) { err.textContent = "Pincode must be 6 digits."; return; }
  err.textContent = "";

  var order = {
    customer: { name: v("name"), phone: v("phone"), address: v("addr"), city: v("city"), pincode: v("pin") },
    payment: v("pay"),
    items: cart.map(function (i) { var p = find(i.id); return { id: i.id, name: p.name, qty: i.q, price: p.price }; }),
    total: total()
  };
  var btn = f.querySelector("button[type=submit]");
  btn.disabled = true; btn.textContent = "Placing order...";

  fetch(ORDER_ENDPOINT, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(order) })
    .then(function (r) { if (!r.ok) throw new Error("bad response"); return r.json(); })
    .then(function () {
      cart = []; save(); updateBadge();
      $("dbody").innerHTML = '<div class="done"><h3>Order received. Thank you!</h3><p>We will call you shortly to confirm.</p></div>';
    })
    .catch(function () {
      btn.disabled = false; btn.textContent = "Place order";
      err.textContent = "We could not place your order. Please try again in a moment.";
    });
}

document.addEventListener("click", function (e) {
  var a = e.target.closest("[data-add]");
  if (a) {
    var id = a.dataset.add, h = cart.filter(function (i) { return i.id === id; })[0];
    if (h) { h.q++; } else { cart.push({ id: id, q: 1 }); }
    save(); updateBadge(); openCart();
    return;
  }
  var d = e.target.closest("[data-d]");
  if (d) change(d.dataset.id, +d.dataset.d);
});
var openButton = $("open-cart"), closeButton = $("close-cart");
if (openButton) openButton.onclick = openCart;
if (closeButton) closeButton.onclick = closeCart;
if (scrim) scrim.onclick = closeCart;
document.addEventListener("keydown", function (e) { if (e.key === "Escape") closeCart(); });
updateBadge();

/* Customer reviews. TODO: replace these placeholders with real customer reviews. */
var REVIEWS = [];
var reviewGrid = $("review-grid");
var reviewsSection = document.querySelector("section[aria-labelledby='customer-reviews']");
if (reviewGrid && REVIEWS.length) {
  reviewGrid.innerHTML = REVIEWS.map(function (r) {
    return '<figure class="review"><div class="stars" aria-label="5 out of 5 stars">★★★★★</div><blockquote>' + esc(r.text) + '</blockquote><figcaption><b>' + esc(r.name) + '</b><span>' + esc(r.place) + '</span></figcaption></figure>';
  }).join("");
} else if (reviewsSection) {
  reviewsSection.hidden = true;
}
})();